public static int spannweite(int[] r) {
    if (r.length == 0) {
        return 0;
    }
    int min = r[0];
    int max = r[0];
    for (int i = 1; i < r.length; i++) {
        if (r[i] < min) {
            min = r[i];
        }
        if (r[i] > max) {
            max = r[i];
        }
    }
    return max - min;
}

